@startuml

class Library {
}

class User {
  + securityDeposit : float
  + phone : string
  + email : string
  + postalAddress : string
}

class BorrowableItem {
  + libraryCode : int
  + location : string
}

class Book extends BorrowableItem {
}

class Magazine extends BorrowableItem {
  + publicationDate : date
}

class CD extends BorrowableItem {
}

class Film extends BorrowableItem {
  + duration : time
}

class VHS extends Film {}

class DVD extends Film {}

class Publisher {}

class Author {}

class Artist {}

class Actor {}

class Loan {
  + loanStartDate : date
  + maxDuration : int
}

class ItemTransferRequest {}

Library "1" -- "*" Library : coordinate
Library "1" -- "*" User : has
Library "1" -- "*" BorrowableItem : has
Library "1" -- "0..*" ItemTransferRequest : receives
Library "0..*" -- "1" ItemTransferRequest : source

User "1" -- "0..3" Loan : makes
BorrowableItem "1" -- "0..1" Loan : is lent to

Book "1..*" -- "1..*" Author : has
Book "1..*" -- "1" Publisher : has
Magazine "1..*" -- "1" Publisher : has
CD "1..*" -- "1" Artist : has
CD "1..*" -- "1" Publisher : has
Film "1..*" -- "1..*" Actor : has
Film "1..*" -- "1" Publisher : has

@enduml

